function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name] || ICONS.room}"/></svg>`;}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function svgElement(name,attrs={},children=[]){const e=document.createElementNS(NS,name);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,String(v)));children.forEach(c=>e.append(c));return e;}
const TYPES = {select:'Seçim aracı',pan:'Alanı kaydır',erase:'Silgi',room:'Oda',wall:'Duvar',door:'Kapı',cover:'Engel / siper',zone:'Bölge',path:'Rota',spawn:'Başlangıç',enemy:'Düşman',objective:'Hedef',pickup:'Eşya',note:'Not'};
