let project=sampleProject();
let selected=new Set(['r5']);
let tool='select',view='2d',snap=true,gridVisible=true;
let zoom=1,pan={x:0,y:0},gesture=null,spaceHeld=false,history=[],future=[],saveTimer,toastTimer,angle=-.68;
const editor=$('#editor'),scene=$('#scene'),selectionGroup=$('#selection'),draft=$('#draft'),wrap=$('#canvasWrap');
function getLayer(id){return project.layers.find(l=>l.id===id);}
function visibleObjects(){return project.objects.filter(o=>getLayer(o.layer)?.visible);}
function bounds(objects=project.objects){let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const o of objects){const pts=o.points || [{x:o.x,y:o.y},{x:o.x2??o.x+(o.w??1),y:o.y2??o.y+(o.h??1)}];for(const p of pts){minX=Math.min(minX,p.x);minY=Math.min(minY,p.y);maxX=Math.max(maxX,p.x);maxY=Math.max(maxY,p.y);}}return minX===Infinity?{x:0,y:0,w:30,h:24}:{x:minX,y:minY,w:Math.max(1,maxX-minX),h:Math.max(1,maxY-minY)};}
function linePoints(o){return o.points?.map(p=>`${p.x*UNIT},${p.y*UNIT}`).join(' ');}
function drawObject(o,{mini=false,exporting=false}={}){
 const g=svgElement('g',{'data-id':o.id,'data-type':o.type}),x=o.x*UNIT,y=o.y*UNIT,w=(o.w||0)*UNIT,h=(o.h||0)*UNIT,color=o.color||COLORS[o.type];
 if(o.type==='room'||o.type==='cover'||o.type==='zone'){
  g.append(svgElement('rect',{x,y,width:w,height:h,fill:color,'fill-opacity':o.type==='zone'?.05:o.type==='room'?.44:.7,stroke:color,'stroke-width':o.type==='room'?3:1.4,'stroke-dasharray':o.type==='zone'?'7 5':'none',rx:o.type==='cover'?1:0,'pointer-events':o.type==='zone'?'stroke':'all'}));
  if(o.type==='room'&&!mini){const labelScale=exporting?1:Math.max(1,.8/zoom);g.append(svgElement('rect',{x:x+5,y:y+5,width:Math.max(0,w-10),height:Math.max(0,h-10),fill:'none',stroke:color,'stroke-opacity':.36,'stroke-width':1}));if(o.w>=5&&o.h>=4){const t=svgElement('text',{x:x+w/2,y:y+h/2-4*labelScale,'text-anchor':'middle',fill:'#c5cdd0','font-size':14*labelScale,'font-family':'DM Sans, sans-serif','font-weight':500,'letter-spacing':1});t.textContent=o.name;const sub=svgElement('text',{x:x+w/2,y:y+h/2+15*labelScale,'text-anchor':'middle',fill:'#929fa5','font-size':11*labelScale,'font-family':'Consolas,monospace'});sub.textContent=`${+(o.w*o.h).toFixed(1)} m² · h ${o.height??3} m`;g.append(t,sub);}}
  if(o.type==='zone'&&!mini){g.append(svgElement('rect',{x,y,width:w,height:h,fill:'url(#zoneHatch)','pointer-events':'none'}));const t=svgElement('text',{x:x+10,y:y+18,fill:color,'font-size':9,'font-family':'Consolas,monospace','letter-spacing':1.2});t.textContent=o.name;g.append(t);}
  if(o.type==='cover'&&!mini){g.append(svgElement('path',{d:`M${x+4} ${y+4}L${x+w-4} ${y+h-4}M${x+w-4} ${y+4}L${x+4} ${y+h-4}`,stroke:'#cad0ce','stroke-opacity':.2,'stroke-width':1}));}
 }else if(o.type==='wall'||o.type==='door'){
  const attrs={x1:x,y1:y,x2:o.x2*UNIT,y2:o.y2*UNIT};if(o.type==='door')g.append(svgElement('line',{...attrs,stroke:'#24282e','stroke-width':10}));g.append(svgElement('line',{...attrs,stroke:color,'stroke-width':o.type==='wall'?5:2,'stroke-dasharray':o.type==='door'?'4 3':'none','stroke-linecap':'square'}));
  if(!mini)g.append(svgElement('line',{...attrs,stroke:'transparent','stroke-width':14}));
 }else if(o.type==='path'){
  g.append(svgElement('polyline',{points:linePoints(o),fill:'none',stroke:color,'stroke-opacity':.78,'stroke-width':2,'stroke-dasharray':'6 6','stroke-linecap':'round','stroke-linejoin':'round'}));
  if(!mini){g.append(svgElement('polyline',{points:linePoints(o),fill:'none',stroke:'transparent','stroke-width':16}));const pts=o.points;for(let i=1;i<pts.length-1;i+=2){const p=pts[i],q=pts[i+1],a=Math.atan2(q.y-p.y,q.x-p.x)*180/Math.PI;g.append(svgElement('path',{d:'M-5-4L1 0l-6 4',transform:`translate(${(p.x+q.x)/2*UNIT} ${(p.y+q.y)/2*UNIT}) rotate(${a})`,fill:'none',stroke:color,'stroke-width':1.6}));}}
 }else if(o.type==='note'){
  if(!mini){g.append(svgElement('rect',{x:x-4,y:y-15,width:Math.max(60,o.name.length*6.8+16),height:26,fill:'#1b1f25',stroke:'#616a78','stroke-opacity':.6,rx:4}));const t=svgElement('text',{x:x+4,y:y+2,fill:color,'font-size':11,'font-family':'DM Sans,sans-serif'});t.textContent=o.name;g.append(t);}
 }else{
  const markerScale=mini||exporting?1:Math.max(1,.7/zoom),r=mini?8:15*markerScale;g.append(svgElement('circle',{cx:x,cy:y,r,fill:'#24282e',stroke:color,'stroke-width':1.5*markerScale}));
  const path=svgElement('path',{d:ICONS[o.type],stroke:color,'stroke-width':1.7,fill:'none','stroke-linecap':'round','stroke-linejoin':'round',transform:`translate(${x-9*markerScale} ${y-9*markerScale}) scale(${.75*markerScale})`});g.append(path);
  if(!mini&&o.type==='spawn'){const t=svgElement('text',{x,y:y+30,'text-anchor':'middle',fill:color,'font-size':9,'font-family':'Consolas,monospace','letter-spacing':1});t.textContent='BAŞLANGIÇ';g.append(t);}
 }
 if(exporting)g.removeAttribute('data-id');return g;
}
function renderScene(){scene.replaceChildren();const objs=visibleObjects();['room','zone','cover','wall','door','path','spawn','enemy','objective','pickup','note'].forEach(type=>objs.filter(o=>o.type===type).forEach(o=>scene.append(drawObject(o))));renderSelection();renderMinimap();if(view==='3d')renderIso();}
function renderSelection(){selectionGroup.replaceChildren();if(view!=='2d')return;for(const o of project.objects.filter(o=>selected.has(o.id)&&getLayer(o.layer)?.visible)){const b=bounds([o]);if(['room','cover','zone'].includes(o.type)){const x=o.x*UNIT,y=o.y*UNIT,w=o.w*UNIT,h=o.h*UNIT;selectionGroup.append(svgElement('rect',{x:x-2,y:y-2,width:w+4,height:h+4,fill:'none',stroke:'#b8ef77','stroke-width':1.5/zoom,'pointer-events':'none'}));if(!getLayer(o.layer)?.locked&&selected.size===1)for(const [name,cx,cy]of[['nw',x,y],['ne',x+w,y],['se',x+w,y+h],['sw',x,y+h]])selectionGroup.append(svgElement('rect',{'data-handle':name,x:cx-4/zoom,y:cy-4/zoom,width:8/zoom,height:8/zoom,fill:'#b8ef77',stroke:'#24282e','stroke-width':1/zoom,cursor:name==='nw'||name==='se'?'nwse-resize':'nesw-resize'}));if(selected.size===1){const t=svgElement('text',{x:x+w/2,y:y-13/zoom,fill:'#b8ef77','text-anchor':'middle','font-size':11/zoom,'font-family':'Consolas,monospace','pointer-events':'none'});t.textContent=`${o.w} × ${o.h} m`;selectionGroup.append(t);}}else selectionGroup.append(svgElement('rect',{x:b.x*UNIT-20,y:b.y*UNIT-20,width:b.w*UNIT+26,height:b.h*UNIT+26,fill:'none',stroke:'#b8ef77','stroke-dasharray':'3 3','stroke-width':1/zoom,'pointer-events':'none'}));}}
function updateTransform(){const t=`translate(${pan.x} ${pan.y}) scale(${zoom})`;[scene,selectionGroup,draft].forEach(g=>g.setAttribute('transform',t));$('#minorGrid').setAttribute('width',project.grid*UNIT);$('#minorGrid').setAttribute('height',project.grid*UNIT);$('#minorGrid path').setAttribute('d',`M${project.grid*UNIT} 0L0 0 0 ${project.grid*UNIT}`);$('#majorGrid').setAttribute('width',project.grid*UNIT*5);$('#majorGrid').setAttribute('height',project.grid*UNIT*5);$('#majorGrid>path').setAttribute('d',`M${project.grid*UNIT*5} 0L0 0 0 ${project.grid*UNIT*5}`);$('#majorGrid').setAttribute('patternTransform',t);$('#gridBackground').setAttribute('fill',gridVisible?'url(#majorGrid)':'#24282e');$('#zoomLabel').textContent=`${Math.round(zoom*100)}%`;$('#scaleLabel').textContent=`${+(90/(UNIT*zoom)).toFixed(1)} metre`;renderScene();}
function fitView(){const b=bounds(visibleObjects()),width=wrap.clientWidth,height=wrap.clientHeight;zoom=Math.max(.15,Math.min(1.3,(width-145)/(b.w*UNIT),(height-195)/(b.h*UNIT)));pan={x:(width-b.w*UNIT*zoom)/2-b.x*UNIT*zoom+8,y:115+(height-190-b.h*UNIT*zoom)/2-b.y*UNIT*zoom};updateTransform();}
function renderLayers(){const counts=project.objects.reduce((a,o)=>(a[o.layer]=(a[o.layer]||0)+1,a),{});$('#layerList').innerHTML=project.layers.map(l=>`<div class="layer-row ${l.visible?'':'muted'}">${icon('layers')}<span class="layer-name">${escapeHtml(l.name)}</span><span class="count">${counts[l.id]||0}</span><button data-layer="${l.id}" data-action="visible" title="${l.visible?'Gizle':'Göster'}" aria-label="${escapeHtml(l.name)} katmanını ${l.visible?'gizle':'göster'}" class="${l.visible?'':'is-off'}">${icon(l.visible?'eye':'eyeOff')}</button><button data-layer="${l.id}" data-action="locked" title="${l.locked?'Kilidi aç':'Kilitle'}" aria-label="${escapeHtml(l.name)} katmanını ${l.locked?'aç':'kilitle'}" class="${l.locked?'is-off':''}">${icon(l.locked?'lock':'unlock')}</button></div>`).join('');}
function field(label,key,value,unit='m'){return `<label>${label}<div class="input-unit"><input data-property="${key}" type="number" step="0.5" ${['w','h','height'].includes(key)?'min="0.1"':''} value="${value??0}" aria-label="${label}"><span>${unit}</span></div></label>`;}
function renderInspector(){const signature=[...selected].sort().join(","),panel=document.querySelector(".right-panel");if(panel.dataset.selection!==signature){panel.scrollTop=0;panel.dataset.selection=signature;}const objs=project.objects.filter(o=>selected.has(o.id));let html='';if(objs.length===1){const o=objs[0],rectangle=['room','cover','zone'].includes(o.type),line=['wall','door'].includes(o.type);html=`<div class="selection-heading"><div class="selection-icon">${icon(o.type)}</div><div><h3>${TYPES[o.type]}</h3><p>${getLayer(o.layer)?.name}${getLayer(o.layer)?.locked?' · Kilitli':''}</p></div></div><div class="inspector-section"><h4>GENEL</h4><label>Öğe adı<input data-property="name" value="${escapeHtml(o.name)}" maxlength="80"></label></div><div class="inspector-section"><h4>KONUM & ÖLÇÜLER</h4><div class="field-grid">${field('X konumu','x',o.x)}${field('Z konumu','y',o.y)}${rectangle?field('Genişlik','w',o.w)+field('Derinlik','h',o.h):''}${line?field('Bitiş X','x2',o.x2)+field('Bitiş Z','y2',o.y2):''}${o.type!=='path'&&o.type!=='note'?field('Yükseklik','height',o.height??3)+field('Kot (Y)','elevation',o.elevation??0):''}</div>${o.type==='room'?`<div class="area-line" style="margin-top:13px;color:#83917d;font:11px Consolas,monospace">Alan: ${+(o.w*o.h).toFixed(2)} m²</div>`:''}</div><div class="inspector-section"><h4>GÖRÜNÜM</h4><label>Öğe rengi</label><div class="swatches">${['#526264','#515d64','#53695c','#6b6055','#565e70','#b8ef77','#e58d82'].map(c=>`<button class="swatch ${o.color===c?'selected':''}" style="--swatch:${c}" data-color="${c}" title="${c}" aria-label="Renk ${c}"></button>`).join('')}</div></div><div class="inspector-section"><h4>LEVEL TASARIMI</h4><label>Oynanış etiketi<input data-property="tag" class="tag-input" value="${escapeHtml(o.tag||'')}" placeholder="Örn. Combat, Safe zone" maxlength="100"></label></div><div class="inspector-actions"><button id="duplicate">${icon('copy')}Çoğalt</button>${rectangle?`<button id="rotate" title="90° döndür" aria-label="90 derece döndür">${icon('rotate')}</button>`:''}<button id="delete" title="Öğeyi sil" aria-label="Öğeyi sil">${icon('trash')}</button></div>`;}else if(objs.length>1){html=`<div class="selection-heading"><div class="selection-icon">${icon('layers')}</div><div><h3>${objs.length} öğe seçildi</h3><p>Shift ile seçime ekle</p></div></div><p class="empty-inspector">Seçili öğeleri birlikte taşıyabilir, çoğaltabilir veya silebilirsin.</p><div class="inspector-actions"><button id="duplicate">${icon('copy')}Çoğalt</button><button id="delete">${icon('trash')}</button></div>`;}else{const area=project.objects.filter(o=>o.type==='room').reduce((sum,o)=>sum+o.w*o.h,0);html=`<div class="empty-inspector">${icon('cursor')}<h3 style="font:500 18px 'Space Grotesk',sans-serif;color:#d2d9e2">Mekânını şekillendir.</h3><p>Özelliklerini düzenlemek için bir öğe seç. Yeni bir alan çizmek için araç kutusunu kullan.</p><div class="overview-stats"><div class="stat"><strong>${project.objects.filter(o=>o.type==='room').length}</strong><small>Oda</small></div><div class="stat"><strong>${Math.round(area)}</strong><small>Toplam m²</small></div></div><div class="project-empty-actions"><button data-tool="room">${icon('room')}Oda çizmeye başla</button><button id="loadExample">${icon('map')}Örnek haritayı yükle</button></div></div>`;}$('#inspector').innerHTML=html;}
function renderMinimap(){const map=$('#minimap');map.replaceChildren();const b=bounds(visibleObjects()),s=Math.min(180/(b.w*UNIT),100/(b.h*UNIT));const g=svgElement('g',{transform:`translate(${10-b.x*UNIT*s} ${9-b.y*UNIT*s}) scale(${s})`});visibleObjects().filter(o=>o.type!=='note').forEach(o=>g.append(drawObject(o,{mini:true})));map.append(g);if(view==='2d')g.append(svgElement('rect',{x:-pan.x/zoom,y:-pan.y/zoom,width:wrap.clientWidth/zoom,height:wrap.clientHeight/zoom,fill:'#b8ef77','fill-opacity':.03,stroke:'#b8ef77','stroke-opacity':.55,'stroke-width':1/s,'pointer-events':'none'}));map.dataset.bounds=JSON.stringify({x:b.x,y:b.y,scale:s});}
function render(){renderScene();renderLayers();renderInspector();$('#projectName').value=project.name;$('#canvasName').textContent=project.name;$('#canvasSubtitle').textContent=project.description||'Serbest tasarım · 1 birim = 1 metre';$('#gridSize').value=project.grid;$('#objectCount').textContent=`${project.objects.length} öğe`;$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function checkpoint(snapshot=JSON.stringify(project)){history.push(snapshot);if(history.length>100)history.shift();future=[];}
function autosave(){clearTimeout(saveTimer);$('#saveState').innerHTML='<i></i> Kaydediliyor';saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE,JSON.stringify(project));$('#saveState').innerHTML='<i></i> Yerel kayıt';}catch{$('#saveState').textContent='Kayıt alanı dolu';notify('Otomatik kayıt kullanılamıyor. JSON indirerek çizimini koru.');}},350);}
function changed(){render();autosave();window.dispatchEvent(new Event("blockout:change"));}
function restore(snapshot){project=JSON.parse(snapshot);selected=new Set([...selected].filter(id=>project.objects.some(o=>o.id===id)));changed();updateTransform();}
function undo(){if(!history.length)return;future.push(JSON.stringify(project));restore(history.pop());}
function redo(){if(!future.length)return;history.push(JSON.stringify(project));restore(future.pop());}
function uid(){return globalThis.crypto?.randomUUID?.()||'o'+Date.now().toString(36)+Math.random().toString(36).slice(2,8);}
function layerFor(type){return ['spawn','enemy','objective','pickup','zone'].includes(type)?'gameplay':['path','note'].includes(type)?'notes':'geometry';}
function snapNumber(n){return +(snap?Math.round(n/project.grid)*project.grid:n).toFixed(2);}
function point(e,aligned=true){const r=wrap.getBoundingClientRect(),x=(e.clientX-r.left-pan.x)/(zoom*UNIT),y=(e.clientY-r.top-pan.y)/(zoom*UNIT);return {x:aligned?snapNumber(x):x,y:aligned?snapNumber(y):y};}
function screenPoint(e){const r=wrap.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};}
function moveObject(o,dx,dy){o.x=+(o.x+dx).toFixed(2);o.y=+(o.y+dy).toFixed(2);if(o.x2!==undefined){o.x2=+(o.x2+dx).toFixed(2);o.y2=+(o.y2+dy).toFixed(2);}if(o.points)o.points=o.points.map(p=>({x:+(p.x+dx).toFixed(2),y:+(p.y+dy).toFixed(2)}));}
function setTool(value){if(!TYPES[value])return;if(view==='3d'&&value!=='select'&&value!=='pan')setView('2d');tool=value;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));wrap.dataset.tool=tool;$('#toolStatus').textContent=TYPES[tool]+(['select','pan','erase'].includes(tool)?'':' aracı');$('#canvasHint span:last-child').textContent={select:'Öğe seç · Shift ile çoklu seçim',pan:'Çizim alanını sürükleyerek kaydır',erase:'Silmek istediğin öğeye tıkla',room:'Odanın köşesinden karşı köşesine sürükle',wall:'Duvarın başlangıcından bitişine sürükle',door:'Kapının açıklığını sürükleyerek belirle',cover:'Engel veya siper alanını sürükleyerek çiz',zone:'Oynanış bölgesini sürükleyerek çiz',path:'Rotayı basılı tutarak çiz · Shift ile düz hat',note:'Not yerleştirmek için tıkla'}[tool]||'Yerleştirmek için çizim alanına tıkla';}
function setView(value){view=value;editor.classList.toggle('hidden',view==='3d');$('#isoCanvas').classList.toggle('hidden',view!=='3d');$('#view2D').classList.toggle('active',view==='2d');$('#view3D').classList.toggle('active',view==='3d');$('.floating-tools').classList.toggle('hidden',view==='3d');$('.orientation').classList.toggle('hidden',view==='3d');if(view==='3d'){$('#canvasHint span:last-child').textContent='Sürükle: döndür · Tekerlek: yakınlaş';renderIso();}else{setTool(tool);renderScene();}}
function zoomAt(factor,cx=wrap.clientWidth/2,cy=wrap.clientHeight/2){const next=Math.max(.15,Math.min(4,zoom*factor));pan.x=cx-(cx-pan.x)*next/zoom;pan.y=cy-(cy-pan.y)*next/zoom;zoom=next;updateTransform();}
function mutateSelection(action){const objs=project.objects.filter(o=>selected.has(o.id)&&!getLayer(o.layer)?.locked);if(!objs.length){notify('Önce düzenlenebilir bir öğe seç.');return;}checkpoint();action(objs);changed();}
function deleteSelected(){mutateSelection(objs=>{const ids=new Set(objs.map(o=>o.id));project.objects=project.objects.filter(o=>!ids.has(o.id));ids.forEach(id=>selected.delete(id));});}
function duplicateSelected(){mutateSelection(objs=>{selected.clear();for(const original of objs){const copy=structuredClone(original);copy.id=uid();copy.name=copy.name+' kopya';moveObject(copy,project.grid*2,project.grid*2);project.objects.push(copy);selected.add(copy.id);}});}
function rotateSelected(){mutateSelection(objs=>{for(const o of objs){if(o.w===undefined||o.h===undefined)continue;const cx=o.x+o.w/2,cy=o.y+o.h/2;[o.w,o.h]=[o.h,o.w];o.x=+(cx-o.w/2).toFixed(2);o.y=+(cy-o.h/2).toFixed(2);}});}
function makeObject(type,p){return {id:uid(),type,name:TYPES[type]+(type==='room'?' '+(project.objects.filter(o=>o.type==='room').length+1):''),x:p.x,y:p.y,color:COLORS[type],layer:layerFor(type),elevation:0,height:type==='room'||type==='wall'?3:type==='door'?2.2:1.2,tag:''};}
function startGesture(e){if(e.button!==0&&e.button!==1)return;if(e.target.closest('button,.minimap,.zoom-bar,.floating-tools'))return;const p=point(e),s=screenPoint(e);if(view==='3d'){gesture={kind:'orbit',start:s,angle};$('#isoCanvas').setPointerCapture(e.pointerId);return;}e.preventDefault();editor.setPointerCapture(e.pointerId);const base={start:p,screen:s,before:JSON.stringify(project),moved:false};
 if(tool==='pan'||spaceHeld||e.button===1){gesture={...base,kind:'pan',pan:{...pan}};wrap.classList.add('dragging');return;}
 const handle=e.target.closest('[data-handle]')?.dataset.handle;
 const object=project.objects.find(o=>o.id===e.target.closest('[data-id]')?.dataset.id);
 if(tool==='select'){
  if(handle&&selected.size===1){const o=project.objects.find(o=>selected.has(o.id));if(!getLayer(o.layer)?.locked)gesture={...base,kind:'resize',id:o.id,handle,original:structuredClone(o)};return;}
  if(object){if(e.shiftKey){if(selected.has(object.id))selected.delete(object.id);else selected.add(object.id);}else if(!selected.has(object.id))selected=new Set([object.id]);renderSelection();renderInspector();const movable=project.objects.filter(o=>selected.has(o.id)&&!getLayer(o.layer)?.locked);if(movable.length)gesture={...base,kind:'move',originals:structuredClone(movable)};return;}
  if(!e.shiftKey)selected.clear();gesture={...base,kind:'marquee',initial:new Set(selected)};renderSelection();renderInspector();return;
 }
 if(tool==='erase'){if(object){if(getLayer(object.layer)?.locked){notify('Bu katman kilitli.');return;}checkpoint();project.objects=project.objects.filter(o=>o.id!==object.id);selected.delete(object.id);changed();}return;}
 const layer=getLayer(layerFor(tool));if(layer?.locked||!layer?.visible){notify('Çizmek için ilgili katmanı görünür yap ve kilidini aç.');return;}
 const o=makeObject(tool,p);
 if(['spawn','enemy','objective','pickup','note'].includes(tool)){if(tool==='note')o.name='Tasarım notu';checkpoint();project.objects.push(o);selected=new Set([o.id]);changed();if(tool==='note'){$('#inspector input[data-property=name]')?.focus();$('#inspector input[data-property=name]')?.select();}return;}
 if(['room','cover','zone'].includes(tool)){o.w=project.grid;o.h=project.grid;}
 if(['wall','door'].includes(tool)){o.x2=p.x;o.y2=p.y;}
 if(tool==='path')o.points=[p,p];gesture={...base,kind:'draw',object:o};draft.replaceChildren(drawObject(o));
}
function moveGesture(e){const raw=point(e,false);$('#coordinates').textContent=`X: ${raw.x.toFixed(1)} · Z: ${raw.y.toFixed(1)} m`;if(!gesture)return;const p=point(e),s=screenPoint(e),g=gesture;if(Math.hypot(s.x-g.screen?.x||0,s.y-g.screen?.y||0)>3)g.moved=true;
 if(g.kind==='orbit'){angle=g.angle+(s.x-g.start.x)*.006;renderIso();return;}
 if(g.kind==='pan'){pan={x:g.pan.x+s.x-g.screen.x,y:g.pan.y+s.y-g.screen.y};updateTransform();return;}
 if(g.kind==='move'){const dx=snapNumber(p.x-g.start.x),dy=snapNumber(p.y-g.start.y);for(const original of g.originals){const o=project.objects.find(o=>o.id===original.id);Object.assign(o,structuredClone(original));moveObject(o,dx,dy);}renderScene();return;}
 if(g.kind==='resize'){const o=project.objects.find(o=>o.id===g.id),r=g.original;let x1=r.x,y1=r.y,x2=r.x+r.w,y2=r.y+r.h;if(g.handle.includes('w'))x1=Math.min(p.x,x2-project.grid);else x2=Math.max(p.x,x1+project.grid);if(g.handle.includes('n'))y1=Math.min(p.y,y2-project.grid);else y2=Math.max(p.y,y1+project.grid);Object.assign(o,{x:+x1.toFixed(2),y:+y1.toFixed(2),w:+(x2-x1).toFixed(2),h:+(y2-y1).toFixed(2)});renderScene();return;}
 if(g.kind==='marquee'){const x=Math.min(p.x,g.start.x),y=Math.min(p.y,g.start.y),w=Math.abs(p.x-g.start.x),h=Math.abs(p.y-g.start.y);draft.replaceChildren(svgElement('rect',{x:x*UNIT,y:y*UNIT,width:w*UNIT,height:h*UNIT,fill:'#b8ef77','fill-opacity':.07,stroke:'#b8ef77','stroke-width':1/zoom,'stroke-dasharray':'4 3'}));selected=new Set(g.initial);for(const o of visibleObjects()){const b=bounds([o]);if(b.x+b.w>=x&&b.x<=x+w&&b.y+b.h>=y&&b.y<=y+h)selected.add(o.id);}renderSelection();return;}
 if(g.kind==='draw'){const o=g.object;if(o.w!==undefined){o.x=Math.min(g.start.x,p.x);o.y=Math.min(g.start.y,p.y);o.w=+Math.abs(p.x-g.start.x).toFixed(2);o.h=+Math.abs(p.y-g.start.y).toFixed(2);if(e.shiftKey)o.w=o.h=Math.max(o.w,o.h);}else if(o.type==='path'){const previous=o.points[o.points.length-1];if(e.shiftKey)o.points=[g.start,p];else if(Math.hypot(p.x-previous.x,p.y-previous.y)>=project.grid*.6)o.points.push(p);}else{o.x2=p.x;o.y2=p.y;if(e.shiftKey){if(Math.abs(p.x-o.x)>Math.abs(p.y-o.y))o.y2=o.y;else o.x2=o.x;}}draft.replaceChildren(drawObject(o));}
}
function finishGesture(e,cancel=false){const g=gesture;if(!g)return;gesture=null;draft.replaceChildren();wrap.classList.remove('dragging');if(cancel){if(g.before){project=JSON.parse(g.before);render();}return;}
 if(g.kind==='draw'){const o=g.object;if(o.w!==undefined&&(o.w<.1||o.h<.1))return;if(o.x2!==undefined&&Math.hypot(o.x2-o.x,o.y2-o.y)<.1)return;if(o.type==='path'&&bounds([o]).w<=1&&bounds([o]).h<=1&&!g.moved)return;checkpoint(g.before);project.objects.push(o);selected=new Set([o.id]);changed();}
 else if(['move','resize'].includes(g.kind)){if(JSON.stringify(project)!==g.before){checkpoint(g.before);changed();}else renderInspector();}
 else if(g.kind==='marquee')renderInspector();
}
function cleanProject(data){
 if(!data||data.version!==1||typeof data.name!=='string'||!Array.isArray(data.objects)||data.objects.length>10000)throw new Error('Geçerli bir Blockout JSON projesi seç.');
 const numeric=v=>typeof v==='number'&&Number.isFinite(v)&&Math.abs(v)<100000;
 const ids=new Set();const objects=data.objects.map(o=>{
  if(!o||typeof o.id!=='string'||ids.has(o.id)||!TYPES[o.type]||['select','pan','erase'].includes(o.type)||!numeric(o.x)||!numeric(o.y)||typeof o.name!=='string')throw new Error('Projede geçersiz veya yinelenen bir öğe var.');ids.add(o.id);
  if(['room','cover','zone'].includes(o.type)&&(!numeric(o.w)||!numeric(o.h)||o.w<=0||o.h<=0))throw new Error('Öğe boyutları geçersiz.');
  if(['wall','door'].includes(o.type)&&(!numeric(o.x2)||!numeric(o.y2)))throw new Error('Duvar veya kapı koordinatları geçersiz.');
  if(o.type==='path'&&(!Array.isArray(o.points)||o.points.length<2||o.points.length>20000||o.points.some(p=>!p||!numeric(p.x)||!numeric(p.y))))throw new Error('Rota koordinatları geçersiz.');
  if(o.height!==undefined&&(!numeric(o.height)||o.height<0||o.height>1000))throw new Error('Yükseklik geçersiz.');if(o.elevation!==undefined&&!numeric(o.elevation))throw new Error('Kot geçersiz.');
  const obj={id:o.id,type:o.type,name:o.name.slice(0,80),x:o.x,y:o.y,layer:LAYERS.some(l=>l.id===o.layer)?o.layer:layerFor(o.type),color:/^#[0-9a-f]{6}$/i.test(o.color)?o.color:COLORS[o.type],tag:typeof o.tag==='string'?o.tag.slice(0,100):'',elevation:o.elevation??0,height:o.height??3};
  for(const key of ['w','h','x2','y2'])if(o[key]!==undefined)obj[key]=o[key];if(o.points)obj.points=o.points.map(p=>({x:p.x,y:p.y}));return obj;
 });
 const layers=structuredClone(LAYERS);for(const l of layers){const found=Array.isArray(data.layers)?data.layers.find(item=>item?.id===l.id):null;if(found){l.visible=found.visible!==false;l.locked=found.locked===true;}}
 return {version:1,name:data.name.slice(0,80)||'İsimsiz level',description:typeof data.description==='string'?data.description.slice(0,160):'Serbest tasarım',grid:[.5,1,2].includes(data.grid)?data.grid:1,layers,objects};
}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function fileName(extension){return (project.name.replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').trim()||'Blockout')+'.'+extension;}
function saveJSON(){download(JSON.stringify(project,null,2),fileName('json'),'application/json');notify('JSON projesi indirildi.');}
function exportSVG(){const b=bounds(visibleObjects()),margin=60,s=svgElement('svg',{xmlns:NS,width:Math.ceil(b.w*UNIT+margin*2),height:Math.ceil(b.h*UNIT+margin*2+50),viewBox:`${b.x*UNIT-margin} ${b.y*UNIT-margin-50} ${b.w*UNIT+margin*2} ${b.h*UNIT+margin*2+50}`});s.append(editor.querySelector('defs').cloneNode(true));s.append(svgElement('rect',{x:b.x*UNIT-margin,y:b.y*UNIT-margin-50,width:b.w*UNIT+margin*2,height:b.h*UNIT+margin*2+50,fill:'#24282e'}));const heading=svgElement('text',{x:b.x*UNIT,y:b.y*UNIT-65,fill:'#e6e9ed','font-size':24,'font-family':'sans-serif'});heading.textContent=project.name+' / BLOCKOUT';s.append(heading);const group=svgElement('g');['room','zone','cover','wall','door','path','spawn','enemy','objective','pickup','note'].forEach(type=>visibleObjects().filter(o=>o.type===type).forEach(o=>group.append(drawObject(o,{exporting:true}))));s.append(group);return new XMLSerializer().serializeToString(s);}
async function exportPNG(){const svg=exportSVG(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const canvas=document.createElement('canvas'),factor=Math.min(2,4096/Math.max(image.width,image.height));canvas.width=Math.ceil(image.width*factor);canvas.height=Math.ceil(image.height*factor);const ctx=canvas.getContext('2d');ctx.scale(factor,factor);ctx.drawImage(image,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error();download(blob,fileName('png'),'image/png');notify('PNG planı indirildi.');}catch{notify('PNG oluşturulamadı. SVG olarak dışa aktarabilirsin.');}finally{URL.revokeObjectURL(url);}}
function geometryBoxes(objects=visibleObjects()){
 const boxes=[],doors=objects.filter(o=>o.type==='door');const add=(name,x,z,w,d,y,h,color)=>{if(w>.001&&d>.001&&h>.001)boxes.push({name,x,z,w,d,y,h,color});};
 function wallSide(room,orientation,fixed,start,end,name){const intervals=[];for(const door of doors){const parallel=orientation==='x'?Math.abs(door.y-door.y2)<.05:Math.abs(door.x-door.x2)<.05;const pos=orientation==='x'?door.y:door.x;if(parallel&&Math.abs(pos-fixed)<.22){const a=Math.max(start,Math.min(orientation==='x'?door.x:door.y,orientation==='x'?door.x2:door.y2));const b=Math.min(end,Math.max(orientation==='x'?door.x:door.y,orientation==='x'?door.x2:door.y2));if(b>a)intervals.push({a,b,height:door.height||2.2});}}
  intervals.sort((a,b)=>a.a-b.a);let cursor=start;const segment=(a,b,y,h)=>orientation==='x'?add(name,a,fixed-.12,b-a,.24,y,h,room.color):add(name,fixed-.12,a,.24,b-a,y,h,room.color);for(const gap of intervals){if(gap.a>cursor)segment(cursor,gap.a,room.elevation||0,room.height||3);const a=Math.max(cursor,gap.a);if(gap.b>a){const height=Math.min(gap.height,room.height||3);segment(a,gap.b,(room.elevation||0)+height,(room.height||3)-height);}cursor=Math.max(cursor,gap.b);}if(cursor<end)segment(cursor,end,room.elevation||0,room.height||3);
 }
 for(const o of objects){if(o.type==='room'){const y=o.elevation||0;add(o.name+'_floor',o.x,o.y,o.w,o.h,y-.15,.15,o.color);wallSide(o,'x',o.y,o.x,o.x+o.w,o.name+'_north');wallSide(o,'x',o.y+o.h,o.x,o.x+o.w,o.name+'_south');wallSide(o,'z',o.x,o.y,o.y+o.h,o.name+'_west');wallSide(o,'z',o.x+o.w,o.y,o.y+o.h,o.name+'_east');}else if(o.type==='cover')add(o.name,o.x,o.y,o.w,o.h,o.elevation||0,o.height||1.2,o.color);else if(o.type==='wall'){const length=Math.hypot(o.x2-o.x,o.y2-o.y);if(length>0)boxes.push({name:o.name,x:o.x,z:o.y,w:length,d:.24,y:o.elevation||0,h:o.height||3,color:o.color,rotation:Math.atan2(o.y2-o.y,o.x2-o.x)});}}
 return boxes;
}
function boxVertices(box){const {x,z,w,d,y,h,rotation=0}=box;return [[0,y,0],[w,y,0],[w,y,d],[0,y,d],[0,y+h,0],[w,y+h,0],[w,y+h,d],[0,y+h,d]].map(([vx,vy,vz])=>[x+vx*Math.cos(rotation)-vz*Math.sin(rotation),vy,z+vx*Math.sin(rotation)+vz*Math.cos(rotation)]);}
function exportOBJ(){let text='# Blockout / units: meters / X horizontal, Y up, Z depth\n# Rooms are open-top shells. Door gaps are cut where aligned with room walls.\n',index=1;for(const b of geometryBoxes(project.objects)){text+='o '+b.name.replace(/[^a-zA-Z0-9_-]/g,'_')+'\n';for(const v of boxVertices(b))text+='v '+v.map(n=>+n.toFixed(4)).join(' ')+'\n';for(const face of [[0,3,2,1],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]])text+='f '+face.map(n=>n+index).join(' ')+'\n';index+=8;}return text;}
function shade(hex,factor){return '#'+hex.slice(1).match(/../g).map(n=>Math.max(0,Math.min(255,Math.round(parseInt(n,16)*factor))).toString(16).padStart(2,'0')).join('');}
function renderIso(){
 const canvas=$('#isoCanvas'),ctx=canvas.getContext('2d'),width=wrap.clientWidth,height=wrap.clientHeight,dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=width*dpr;canvas.height=height*dpr;ctx.scale(dpr,dpr);ctx.fillStyle='#24282e';ctx.fillRect(0,0,width,height);
 const b=bounds(visibleObjects()),center={x:b.x+b.w/2,z:b.y+b.h/2},co=Math.cos(angle),si=Math.sin(angle);
 const fitted2D=Math.max(.15,Math.min(1.3,(width-145)/(b.w*UNIT),(height-195)/(b.h*UNIT)));
 const projectedWidth=Math.abs(co)*b.w+Math.abs(si)*b.h,projectedDepth=Math.abs(si)*b.w+Math.abs(co)*b.h;
 const s=Math.max(2,Math.min((width-100)/projectedWidth,(height-175)/(projectedDepth*.48+5)))*Math.sqrt(zoom/fitted2D);
 const projection=([x,y,z])=>{x-=center.x;z-=center.z;return {x:width/2+(x*co-z*si)*s,y:height*.6+(x*si+z*co)*s*.48-y*s*.88,depth:x*si+z*co-y*.04};};
 if(gridVisible){ctx.strokeStyle='#3b414a';ctx.lineWidth=.7;const extent=Math.ceil(Math.max(b.w,b.h)/5)*5+10;for(let i=-extent;i<=extent;i+=5){for(const line of [[[center.x+i,0,center.z-extent],[center.x+i,0,center.z+extent]],[[center.x-extent,0,center.z+i],[center.x+extent,0,center.z+i]]]){const a=projection(line[0]),c=projection(line[1]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(c.x,c.y);ctx.stroke();}}}
 const faces=[];for(const box of geometryBoxes()){const v=boxVertices(box).map(projection);for(const [indices,factor]of [[[4,5,6,7],1.23],[[0,1,5,4],.78],[[1,2,6,5],.98],[[2,3,7,6],.86],[[3,0,4,7],.92]]){const pts=indices.map(i=>v[i]);faces.push({pts,color:shade(box.color||'#526264',factor),depth:pts.reduce((sum,p)=>sum+p.depth,0)/4});}}
 faces.sort((a,c)=>a.depth-c.depth);for(const f of faces){ctx.beginPath();f.pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=f.color;ctx.fill();ctx.strokeStyle='#222b30';ctx.lineWidth=.65;ctx.stroke();}
 for(const o of visibleObjects().filter(o=>['spawn','enemy','objective','pickup'].includes(o.type))){const p=projection([o.x,(o.elevation||0)+1.8,o.y]);ctx.fillStyle=o.color;ctx.strokeStyle='#1c242a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,7,0,Math.PI*2);ctx.fill();ctx.stroke();const ground=projection([o.x,o.elevation||0,o.y]);ctx.strokeStyle=o.color;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x,p.y+7);ctx.lineTo(ground.x,ground.y);ctx.stroke();}
 ctx.fillStyle='#778695';ctx.font='11px Consolas, monospace';ctx.fillText('X / Y / Z · METRE',24,height-91);
}
document.addEventListener('click',e=>{
 const toolButton=e.target.closest('[data-tool]');if(toolButton){setTool(toolButton.dataset.tool);return;}
 const layerButton=e.target.closest('[data-layer]');if(layerButton){checkpoint();const layer=getLayer(layerButton.dataset.layer);layer[layerButton.dataset.action]=!layer[layerButton.dataset.action];if(!layer.visible)selected=new Set([...selected].filter(id=>project.objects.find(o=>o.id===id)?.layer!==layer.id));changed();return;}
 const colorButton=e.target.closest('[data-color]');if(colorButton){mutateSelection(objects=>objects.forEach(o=>o.color=colorButton.dataset.color));return;}
 const close=e.target.closest('[data-close]');if(close)$('#'+close.dataset.close).close();
 if(e.target.closest('#duplicate'))duplicateSelected();if(e.target.closest('#delete'))deleteSelected();if(e.target.closest('#rotate'))rotateSelected();
 if(e.target.closest('#loadExample')){window.dispatchEvent(new Event("blockout:detach"));checkpoint();project=sampleProject();selected=new Set(['r5']);changed();fitView();notify('Örnek harita yüklendi. Önceki çizimi Ctrl+Z ile geri alabilirsin.');}
 if(!e.target.closest('.export-wrap'))$('#exportMenu').classList.add('hidden');
 const exportButton=e.target.closest('[data-export]');if(exportButton){const type=exportButton.dataset.export;$('#exportMenu').classList.add('hidden');if(type==='json')saveJSON();if(type==='png')exportPNG();if(type==='svg'){download(exportSVG(),fileName('svg'),'image/svg+xml');notify('SVG planı indirildi.');}if(type==='obj'){if(!geometryBoxes(project.objects).length){notify('OBJ için önce bir oda, duvar veya siper çiz.');return;}download(exportOBJ(),fileName('obj'),'text/plain');notify('3D OBJ indirildi · 1 birim = 1 metre.');}}
});
$('#inspector').addEventListener('change',e=>{const key=e.target.dataset.property;if(!key)return;const o=project.objects.find(o=>selected.has(o.id));if(!o||getLayer(o.layer)?.locked){notify('Bu katman kilitli.');renderInspector();return;}let value=e.target.type==='number'?Number(e.target.value):e.target.value.trim();if(e.target.type==='number'&&(!Number.isFinite(value)||e.target.value===''||Math.abs(value)>99999||(['w','h','height'].includes(key)&&value<=0))){notify('Geçerli bir ölçü gir.');renderInspector();return;}if(key==='name'&&!value)value=TYPES[o.type];checkpoint();if(key==='x'||key==='y')moveObject(o,key==='x'?value-o.x:0,key==='y'?value-o.y:0);else o[key]=value;changed();});
$('#projectName').addEventListener('change',e=>{checkpoint();project.name=e.target.value.trim()||'İsimsiz level';changed();});
