function newProject(){window.dispatchEvent(new Event("blockout:detach"));checkpoint();project={version:1,name:'İsimsiz level',description:'Serbest tasarım · Yeni bir fikir',grid:1,layers:structuredClone(LAYERS),objects:[]};selected.clear();$('#newDialog').close();setView('2d');setTool('room');changed();fitView();notify('Boş harita hazır. Sürükleyerek ilk odanı çiz.');}
$('#confirmNew').addEventListener('click',newProject);$('#saveThenNew').addEventListener('click',()=>{saveJSON();newProject();});
wrap.addEventListener('pointerdown',startGesture);wrap.addEventListener('pointermove',moveGesture);wrap.addEventListener('pointerup',finishGesture);wrap.addEventListener('pointercancel',e=>finishGesture(e,true));
wrap.addEventListener('wheel',e=>{if(e.target.closest('button,.minimap'))return;e.preventDefault();const s=screenPoint(e);zoomAt(Math.exp(-e.deltaY*.0014),s.x,s.y);},{passive:false});
$('#minimap').addEventListener('pointerdown',e=>{e.stopPropagation();if(view==='3d')return;const r=$('#minimap').getBoundingClientRect(),b=JSON.parse($('#minimap').dataset.bounds),x=(e.clientX-r.left)/r.width*200,y=(e.clientY-r.top)/r.height*118;pan={x:wrap.clientWidth/2-((x-10)/b.scale+b.x*UNIT)*zoom,y:wrap.clientHeight/2-((y-9)/b.scale+b.y*UNIT)*zoom};updateTransform();});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;if(mod&&['z','y','s','d','a'].includes(key)){e.preventDefault();if(key==='z')e.shiftKey?redo():undo();if(key==='y')redo();if(key==='s')saveJSON();if(key==='d')duplicateSelected();if(key==='a'){selected=new Set(visibleObjects().map(o=>o.id));renderSelection();renderInspector();}return;}if(e.code==='Space'){e.preventDefault();spaceHeld=true;wrap.style.cursor='grab';return;}if(key==='delete'||key==='backspace'){e.preventDefault();deleteSelected();return;}if(key==='escape'){if(gesture)finishGesture(null,true);else{selected.clear();setTool('select');renderSelection();renderInspector();}$('#exportMenu').classList.add('hidden');return;}if(key==='f'){fitView();return;}if(key==='?'||key==='/'){$('#helpDialog').showModal();return;}const shortcut={v:'select',h:'pan',e:'erase',r:'room',w:'wall',d:'door',c:'cover',z:'zone',p:'path',n:'note'};if(shortcut[key])setTool(shortcut[key]);if(['arrowup','arrowdown','arrowleft','arrowright'].includes(key)){e.preventDefault();const step=project.grid*(e.shiftKey?5:1);mutateSelection(objects=>objects.forEach(o=>moveObject(o,key==='arrowleft'?-step:key==='arrowright'?step:0,key==='arrowup'?-step:key==='arrowdown'?step:0)));}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){spaceHeld=false;wrap.style.cursor='';}});window.addEventListener('blur',()=>{spaceHeld=false;wrap.style.cursor='';if(gesture)finishGesture(null,true);});
