let resizeTimer;new ResizeObserver(()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(view==='3d')renderIso();else updateTransform();},80);}).observe(wrap);
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const definitions=[{name:'read_level_project',title:'Level projesini oku',description:'Read the current level project, geometry and gameplay markers in meters.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>structuredClone(project)},{name:'add_level_objects',title:'Level öğeleri ekle',description:'Add a batch of room, wall, cover, door or gameplay objects to the current editable project. Coordinates use meters; Y on the 2D plan maps to Z in 3D. Each object needs type, name, x and y. Rectangles need w/h, lines need x2/y2, routes need points. Uses the same undo and autosave as the visible editor.',inputSchema:{type:'object',properties:{objects:{type:'array',minItems:1,maxItems:100,items:{type:'object',properties:{type:{type:'string',enum:['room','wall','door','cover','zone','path','spawn','enemy','objective','pickup','note']},name:{type:'string'},x:{type:'number'},y:{type:'number'},w:{type:'number'},h:{type:'number'},x2:{type:'number'},y2:{type:'number'},height:{type:'number'},elevation:{type:'number'},points:{type:'array',items:{type:'object',properties:{x:{type:'number'},y:{type:'number'}},required:['x','y'],additionalProperties:false}}},required:['type','name','x','y'],additionalProperties:false}}},required:['objects'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Array.isArray(input.objects)||!input.objects.length||input.objects.length>100)throw new Error('Provide 1 to 100 valid objects.');const additions=input.objects.map(o=>({...makeObject(o.type,{x:o.x,y:o.y}),...o,id:uid(),layer:layerFor(o.type),color:COLORS[o.type]}));if(additions.some(o=>getLayer(o.layer)?.locked||!getLayer(o.layer)?.visible))throw new Error('Target layer is hidden or locked.');const validated=cleanProject({...project,objects:[...project.objects,...additions]});checkpoint();project=validated;selected=new Set(additions.map(o=>o.id));changed();return {added:additions.length,ids:additions.map(o=>o.id)};}}];for(const definition of definitions){try{Promise.resolve(context.registerTool(definition,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
try{const saved=localStorage.getItem(STORAGE);if(saved){project=cleanProject(JSON.parse(saved));selected.clear();}}catch{notify('Yerel kayıt okunamadı; örnek harita açıldı.');}
